function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || nums1.length < 1 || nums1.length > 100) return 'nums1 needs 1 to 100 values.';
  if (!Array.isArray(nums2) || nums2.length !== nums1.length) return 'nums2 must be as long as nums1.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each value is an integer from 0 to 100000.';
  const a = [...nums1].sort((x, y) => x - y), b = [...nums2].sort((x, y) => x - y);
  if (a.some((v, i) => v !== b[i])) return 'nums2 must contain exactly the values of nums1.';
  return null;
}

