function anagramMappings(nums1, nums2) {
  const positions = new Map();
  for (let j = 0; j < nums2.length; j++) {
    if (!positions.has(nums2[j])) {
      positions.set(nums2[j], []);
    }
    positions.get(nums2[j]).push(j);
  }

  const mapping = [];
  for (const value of nums1) {
    mapping.push(positions.get(value).pop());
  }
  return mapping;
}

