function anagramMappings(nums1, nums2) {
  // For each value, scan nums2 from the left for the first unused equal value.
  const used = new Array(nums2.length).fill(false);
  return nums1.map(value => {
    let j = 0;
    while (used[j] || nums2[j] !== value) j++;
    used[j] = true;
    return j;
  });
}

