function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const span = rand() < 0.5 ? (size === 'large' ? 20 : 4) : 100000;
  const nums1 = Array.from({ length: n }, () => Math.floor(rand() * (span + 1)));
  const nums2 = [...nums1];
  for (let i = n - 1; i > 0; i--) {
    const k = Math.floor(rand() * (i + 1));
    [nums2[i], nums2[k]] = [nums2[k], nums2[i]];
  }
  return [nums1, nums2];
}
